//! Persistent fixed marketplace payloads. Long unchanged text is Arc-shared;
//! ordinary updates decode only the actual changed original field JSON.
use super::*;
use super::governance_rows::{Scalar,scalar};
use oasis7_world_state::incremental_module_marketplace::ModuleMarketplaceFieldV1 as Field;
use std::{sync::Arc,cell::RefCell,mem::size_of};
use serde::Serialize;
pub(super) struct OriginalMarketRecordDataV1{field:Field,values:[Option<Arc<Scalar>>;11],_fee:MemoryReservation}
fn reserve(common:&mut FormalBoundedContextV1<'_>,n:usize)->Result<MemoryReservation,BodyMutationError>{common.charge(1,n as u64).map_err(paid)?;common.memory().reserve(n,MemoryClass::Ordinary).map_err(ValueTreeError::Memory).map_err(Into::into)}
fn names(field:Field)->&'static[&'static str]{match field{Field::ArtifactListings=>&["order_id","seller_agent_id","price_kind","price_amount","listed_at"],Field::ArtifactBids=>&["order_id","bidder_agent_id","price_kind","price_amount","bid_at"],Field::VisualEntities=>&["entity_id","module_id","kind","label_present","label_text","anchor_kind","anchor_agent_id","anchor_location_id","anchor_x_cm","anchor_y_cm","anchor_z_cm"]}}
#[derive(Debug)]struct CodecCause{error:serde_json::Error,_fee:MemoryReservation}
impl std::fmt::Display for CodecCause{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{self.error.fmt(f)}}impl std::error::Error for CodecCause{}
fn decode(bytes:&[u8],common:&mut FormalBoundedContextV1<'_>)->Result<(serde_json::Value,MemoryReservation),BodyMutationError>{let n=bytes.len().checked_mul(256).and_then(|n|n.checked_add(65536)).ok_or_else(||invalid("marketplace scalar phase"))?;let fee=reserve(common,n)?;common.charge(bytes.len()as u64,bytes.len()as u64).map_err(paid)?;let result=serde_json::from_slice(bytes);common.consume_steps(0).map_err(paid)?;match result{Ok(value)=>Ok((value,fee)),Err(error)=>Err(paid(CodecCause{error,_fee:fee}))}}
impl OriginalMarketRecordDataV1{
 pub(super) fn empty_for_new_v1(field:Field,common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;Ok(Arc::new(Self{field,values:std::array::from_fn(|_|None),_fee:fee}))}
 pub(super) fn from_original_qualified_json_v1(field:Field,bytes:&[u8],common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{let(value,_phase)=decode(bytes,common)?;let serde_json::Value::Object(mut values)=value else{return Err(invalid("marketplace actual object"))};let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;let mut out=Self{field,values:std::array::from_fn(|_|None),_fee:fee};
  if field==Field::VisualEntities{
   let label=values.remove("label").ok_or_else(||invalid("marketplace original label"))?;
   values.insert("label_present".into(),serde_json::Value::Bool(!label.is_null()));if !label.is_null(){values.insert("label_text".into(),label);}
   let serde_json::Value::Object(mut anchor)=values.remove("anchor").ok_or_else(||invalid("marketplace original anchor"))?else{return Err(invalid("marketplace original anchor kind"))};
   let kind=anchor.remove("type").ok_or_else(||invalid("marketplace original anchor type"))?;
   let serde_json::Value::Object(mut data)=anchor.remove("data").ok_or_else(||invalid("marketplace original anchor data"))?else{return Err(invalid("marketplace original anchor data kind"))};
   match kind.as_str(){Some("agent")=>{values.insert("anchor_kind".into(),0u64.into());values.insert("anchor_agent_id".into(),data.remove("agent_id").ok_or_else(||invalid("marketplace original anchor agent"))?);},Some("location")=>{values.insert("anchor_kind".into(),1u64.into());values.insert("anchor_location_id".into(),data.remove("location_id").ok_or_else(||invalid("marketplace original anchor location"))?);},Some("absolute")=>{values.insert("anchor_kind".into(),2u64.into());let serde_json::Value::Object(mut pos)=data.remove("pos").ok_or_else(||invalid("marketplace original anchor pos"))?else{return Err(invalid("marketplace original anchor pos kind"))};for(name,target)in[("x_cm","anchor_x_cm"),("y_cm","anchor_y_cm"),("z_cm","anchor_z_cm")]{common.consume_steps(1).map_err(paid)?;values.insert(target.into(),pos.remove(name).ok_or_else(||invalid("marketplace original pos scalar"))?);}},_=>return Err(invalid("marketplace original anchor variant"))}
  }
  for(index,name)in names(field).iter().enumerate(){common.consume_steps(1).map_err(paid)?;if let Some(value)=values.remove(*name){out.values[index]=Some(scalar(value,common)?);}}
  let out=Arc::new(out);out.validate_complete_v1(common)?;Ok(out)
 }
 pub(super) fn with_actual_patch_v1(&self,name:&str,bytes:Option<&[u8]>,common:&mut FormalBoundedContextV1<'_>)->Result<Arc<Self>,BodyMutationError>{self.validate_context(common)?;common.charge(11,512).map_err(paid)?;let index=names(self.field).iter().position(|actual|*actual==name).ok_or_else(||invalid("marketplace fixed scalar path"))?;let value=if let Some(bytes)=bytes{let(value,_phase)=decode(bytes,common)?;Some(scalar(value,common)?)}else{None};let fee=reserve(common,size_of::<Self>()+2*size_of::<usize>())?;let mut values=self.values.clone();values[index]=value;Ok(Arc::new(Self{field:self.field,values,_fee:fee}))}
 pub(super) fn validate_context(&self,common:&mut FormalBoundedContextV1<'_>)->Result<(),BodyMutationError>{common.consume_steps(1).map_err(paid)?;if !self._fee.uses_budget(common.memory()){return Err(invalid("marketplace fixed source pool"))}Ok(())}
 fn value(&self,name:&str)->Result<&serde_json::Value,BodyMutationError>{let index=names(self.field).iter().position(|actual|*actual==name).ok_or_else(||invalid("marketplace fixed source field"))?;self.values[index].as_ref().map(|v|v.value()).ok_or_else(||invalid("marketplace actual scalar missing"))}
 fn uint(&self,name:&str)->Result<u64,BodyMutationError>{self.value(name)?.as_u64().ok_or_else(||invalid("marketplace unsigned scalar"))}
 fn sint(&self,name:&str)->Result<i64,BodyMutationError>{self.value(name)?.as_i64().ok_or_else(||invalid("marketplace signed scalar"))}
 fn text(&self,name:&str)->Result<&str,BodyMutationError>{self.value(name)?.as_str().ok_or_else(||invalid("marketplace text scalar"))}
 fn price_kind(&self)->Result<oasis7_agent_api::world_action::ResourceKind,BodyMutationError>{use oasis7_agent_api::world_action::ResourceKind as R;let value=self.value("price_kind")?;match(value.as_str(),value.as_u64()){(Some("electricity"),_)|(_,Some(0))=>Ok(R::Electricity),(Some("data"),_)|(_,Some(1))=>Ok(R::Data),_=>Err(invalid("marketplace resource scalar"))}}
 pub(super) fn validate_complete_v1(&self,common:&mut FormalBoundedContextV1<'_>)->Result<(),BodyMutationError>{self.validate_context(common)?;common.charge(128,8192).map_err(paid)?;match self.field{Field::ArtifactListings|Field::ArtifactBids=>{self.uint("order_id")?;self.text(names(self.field)[1])?;self.price_kind()?;self.sint("price_amount")?;self.uint(names(self.field)[4])?;},Field::VisualEntities=>{for name in["entity_id","module_id","kind"]{self.text(name)?;}if self.value("label_present")?.as_bool().ok_or_else(||invalid("marketplace label presence"))?{self.text("label_text")?;}match self.uint("anchor_kind")?{0=>{self.text("anchor_agent_id")?;},1=>{self.text("anchor_location_id")?;},2=>{for name in["anchor_x_cm","anchor_y_cm","anchor_z_cm"]{self.sint(name)?;}},_=>return Err(invalid("marketplace anchor variant"))}}}Ok(())}
 pub(super) fn serialization_v1<'a,'b,'c>(&'a self,common:&'a RefCell<&'b mut FormalBoundedContextV1<'c>>,first:&'a RefCell<Option<BodyMutationError>>)->MarketRecordSerializeV1<'a,'b,'c>{MarketRecordSerializeV1{data:self,common,first}}
}
pub(super) struct MarketRecordSerializeV1<'a,'b,'c>{data:&'a OriginalMarketRecordDataV1,common:&'a RefCell<&'b mut FormalBoundedContextV1<'c>>,first:&'a RefCell<Option<BodyMutationError>>}
impl Serialize for MarketRecordSerializeV1<'_,'_,'_>{fn serialize<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{use serde::ser::Error as _;macro_rules! get{($e:expr)=>{match $e{Ok(v)=>v,Err(error)=>{if self.first.borrow().is_none(){*self.first.borrow_mut()=Some(error)}return Err(S::Error::custom("marketplace actual source"))}}};}let data=self.data;get!(data.validate_complete_v1(&mut self.common.borrow_mut()));match data.field{
 Field::ArtifactListings=>oasis7_world_state::ModuleArtifactListingProjectionFieldsV1{order_id:get!(data.uint("order_id")),seller_agent_id:get!(data.text("seller_agent_id")),price_kind:get!(data.price_kind()),price_amount:get!(data.sint("price_amount")),listed_at:get!(data.uint("listed_at"))}.serialize(s),
 Field::ArtifactBids=>oasis7_world_state::ModuleArtifactBidProjectionFieldsV1{order_id:get!(data.uint("order_id")),bidder_agent_id:get!(data.text("bidder_agent_id")),price_kind:get!(data.price_kind()),price_amount:get!(data.sint("price_amount")),bid_at:get!(data.uint("bid_at"))}.serialize(s),
 Field::VisualEntities=>{use oasis7_agent_api::{world_entity::{ModuleVisualAnchorProjectionDataV1 as A,ModuleVisualEntityProjectionFieldsV1 as V},world_action::GeoPos};let position;let anchor=match get!(data.uint("anchor_kind")){0=>A::Agent{agent_id:get!(data.text("anchor_agent_id"))},1=>A::Location{location_id:get!(data.text("anchor_location_id"))},2=>{position=GeoPos::new(get!(data.sint("anchor_x_cm")),get!(data.sint("anchor_y_cm")),get!(data.sint("anchor_z_cm")));A::Absolute{pos:&position}},_=>return Err(S::Error::custom("marketplace anchor kind"))};let label=if get!(data.value("label_present")).as_bool()==Some(true){Some(get!(data.text("label_text")))}else{None};V{entity_id:get!(data.text("entity_id")),module_id:get!(data.text("module_id")),kind:get!(data.text("kind")),label,anchor:&anchor}.serialize(s)}
}}}
impl OriginalMarketRecordDataV1{pub(super) fn actual_anchor_json_v1(&self,common:&mut FormalBoundedContextV1<'_>)->Result<ReservedValue<Vec<u8>>,BodyMutationError>{self.validate_complete_v1(common)?;if self.field!=Field::VisualEntities{return Err(invalid("marketplace anchor profile"))}use oasis7_agent_api::{world_entity::ModuleVisualAnchorProjectionDataV1 as A,world_action::GeoPos};let position;let anchor=match self.uint("anchor_kind")?{0=>A::Agent{agent_id:self.text("anchor_agent_id")?},1=>A::Location{location_id:self.text("anchor_location_id")?},2=>{position=GeoPos::new(self.sint("anchor_x_cm")?,self.sint("anchor_y_cm")?,self.sint("anchor_z_cm")?);A::Absolute{pos:&position}},_=>return Err(invalid("marketplace anchor kind"))};super::capture_projection_json_data_v1(&anchor,common)}}
